  "rl.promo.h": "प्रमोशन",
  "rl.promo": "आखिरी पंक्ति पर पहुँचा प्यादा वज़ीर, हाथी, ऊँट या घोड़ा बन जाता है।",
  "rl.check.h": "शह",
